import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"Commands and Permissions","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/forge/commands.md","filePath":"en/modules/forge/commands.md","lastUpdated":0}`),a={name:`en/modules/forge/commands.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="commands-and-permissions" tabindex="-1">Commands and Permissions <a class="header-anchor" href="#commands-and-permissions" aria-label="Permalink to “Commands and Permissions”">​</a></h1><p>The main command of EmakiForge is <code>/emakiforge</code>, with <code>/eforge</code> and <code>/ef</code> as aliases. Commands open the forge GUI, open the recipe book, list recipes, reload configuration, and print debug information.</p><p>The root command requires <code>emakiforge.use</code> (default true). Additional subcommand permissions are listed below.</p><table tabindex="0"><thead><tr><th>Command</th><th>Permission</th><th>Description</th></tr></thead><tbody><tr><td><code>/ef help</code></td><td>Root permission only</td><td>Show command help. Running the root command with no arguments also shows help.</td></tr><tr><td><code>/ef forge</code></td><td>Root permission only</td><td>Open the forge GUI. Players only.</td></tr><tr><td><code>/ef book</code></td><td><code>emakiforge.book</code> or <code>emakiforge.admin</code></td><td>Open the recipe book. Players only.</td></tr><tr><td><code>/ef list recipe</code></td><td><code>emakiforge.admin</code></td><td>List loaded recipes with display names. <code>recipes</code> is also accepted, but tab completion only suggests <code>recipe</code>.</td></tr><tr><td><code>/ef reload</code></td><td><code>emakiforge.reload</code> or <code>emakiforge.admin</code></td><td>Reload config, language, GUI templates, and recipes.</td></tr><tr><td><code>/ef convert-legacy [confirm]</code></td><td><code>emakiforge.admin</code></td><td>Migrates legacy <code>item_sources</code> entries in <code>recipes/</code> materials and blueprint requirements to the current matcher shape; material entries retain the legacy key where required. Without an argument it performs a dry run; <code>confirm</code> (or <code>--apply</code>) writes files and leaves a <code>.bak</code> backup.</td></tr><tr><td><code>/ef debug stats</code></td><td><code>emakiforge.debug</code> or <code>emakiforge.admin</code></td><td>Print runtime metrics and the recipe load report (<code>status</code> is equivalent).</td></tr><tr><td><code>/ef debug &lt;player|module|...&gt;</code></td><td><code>emakiforge.debug</code> or <code>emakiforge.admin</code></td><td>Delegate to the CoreLib debug command.</td></tr></tbody></table><p>Available debug submodules: <code>recipe</code>, <code>forge</code>, <code>gui</code>, <code>pdc</code>.</p><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to “Permissions”">​</a></h2><table tabindex="0"><thead><tr><th>Permission</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>emakiforge.use</code></td><td>true</td><td>Allows use of the root command and forge GUI.</td></tr><tr><td><code>emakiforge.book</code></td><td>true</td><td>Allows opening the recipe book.</td></tr><tr><td><code>emakiforge.reload</code></td><td>op</td><td>Allows reloading configuration.</td></tr><tr><td><code>emakiforge.debug</code></td><td>op</td><td>Allows debug output.</td></tr><tr><td><code>emakiforge.admin</code></td><td>op</td><td>Allows administrative operations.</td></tr></tbody></table>`,7)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};